//go:build ignore

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

struct {
    __uint(type, BPF_MAP_TYPE_REUSEPORT_SOCKARRAY);
    __uint(max_entries, 128);
    __type(key, __u32);
    __type(value, __u32);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_udp_targets SEC(".maps");

// EVOLVE-BLOCK-START
/*
 * Agent UDP selector: GET/SCAN-aware split with a dedicated scan worker.
 *
 * Approach
 * --------
 * Workload: ~99.5% GET, very rare but ~2ms SCANs. With purely random
 * balancing, a GET can frequently land behind a SCAN in the same worker's
 * queue, inflating GET tail latency once queues form.
 *
 * This selector keeps the original agent design (stateless, per-packet
 * random choice within the active worker set) but adds a minimal parser for
 * the UDP payload prefix:
 *
 *   - UDP payload = reuse->data + 8 (after UDP header).
 *   - Classify request by ASCII prefix:
 *       "GET "  -> GET
 *       "SCAN " -> SCAN
 *       other   -> UNKNOWN (falls back to unbiased random).
 *
 * Slot selection:
 *   - Let active = min(agent_state.active, 128).
 *   - If active <= 1, or classification fails: per-packet random over
 *     [0, active) as before.
 *   - If active >= 2:
 *       * Reserve exactly 1 worker (highest index) for SCAN traffic.
 *       * GET: random index in [0, active-1).
 *       * SCAN: random index in [active-1, active), which is always the
 *         last worker when there is just one SCAN slot.
 *
 * This isolates long SCANs on a dedicated worker, so GETs almost never sit
 * behind them, reducing GET p99 queueing while preserving overall throughput.
 *
 * Implementation notes
 * --------------------
 * - Only existing maps are used: pebble_agent_state and pebble_udp_targets.
 * - No additional state; per-packet logic is O(1) with a few byte loads.
 * - RNG -> index uses 32x32->64 multiply and upper-32-bit shift to avoid
 *   division while keeping uniformity.
 * - Verifier-friendly: no loops, bounded pointer checks against data_end,
 *   and a single bpf_sk_select_reuseport() call.
 */

struct agent_state {
    __u32 active;
    __u32 pad;
};

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct agent_state);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_agent_state SEC(".maps");

static __always_inline __u32 pick_slot(__u32 rnd, __u32 range)
{
    /* Map rnd uniformly into [0, range) without a division. */
    return ((__u64)rnd * range) >> 32;
}

SEC("sk_reuseport/selector")
enum sk_action agent_udp_selector(struct sk_reuseport_md *reuse)
{
    __u32 key = 0;
    struct agent_state *state = bpf_map_lookup_elem(&pebble_agent_state, &key);
    if (!state)
        return SK_PASS;

    __u32 active = state->active;
    if (active == 0)
        return SK_PASS;

    /* Clamp to the REUSEPORT array size (128). */
    if (active > 128)
        active = 128;

    if (active == 0)
        return SK_PASS;

    /* Pre-draw randomness for this packet. */
    __u32 rnd = bpf_get_prandom_u32();
    __u32 slot;

    /* If we cannot meaningfully split, retain unbiased random balancing. */
    if (active <= 1)
        goto random_all;

    /* Attempt minimal payload classification: "GET " vs "SCAN ". */
    __u8 *data = (__u8 *)(long)reuse->data;
    __u8 *data_end = (__u8 *)(long)reuse->data_end;

    /* Ensure UDP header (8 bytes) is present. */
    if (data + 8 > data_end)
        goto random_all;

    __u8 *payload = data + 8;

    /* Need at least 4 bytes for "GET " checks. */
    if (payload + 4 > data_end)
        goto random_all;

    __u8 c0 = payload[0];
    __u8 c1 = payload[1];
    __u8 c2 = payload[2];
    __u8 c3 = payload[3];

    int is_get = 0;
    int is_scan = 0;

    if (c0 == 'G' && c1 == 'E' && c2 == 'T' && c3 == ' ') {
        is_get = 1;
    } else if (payload + 5 <= data_end) {
        __u8 c4 = payload[4];
        if (c0 == 'S' && c1 == 'C' && c2 == 'A' && c3 == 'N' && c4 == ' ') {
            is_scan = 1;
        }
    }

    /* Reserve exactly one worker (highest index) for SCAN traffic. */
    if (is_scan) {
        __u32 scan_slots = 1;
        __u32 get_slots = active - scan_slots; /* >= 1 because active >= 2 */
        __u32 idx_in_scan = pick_slot(rnd, scan_slots);
        slot = get_slots + idx_in_scan;       /* in [get_slots, active) */
    } else if (is_get) {
        __u32 scan_slots = 1;
        __u32 get_slots = active - scan_slots;
        slot = pick_slot(rnd, get_slots);     /* in [0, get_slots) */
    } else {
        /* Unknown method: fall back to unbiased random over all workers. */
        goto random_all;
    }

    (void)bpf_sk_select_reuseport(reuse, &pebble_udp_targets, &slot, 0);
    return SK_PASS;

random_all:
    slot = pick_slot(rnd, active);
    (void)bpf_sk_select_reuseport(reuse, &pebble_udp_targets, &slot, 0);
    return SK_PASS;
}
// EVOLVE-BLOCK-END

char _license[] SEC("license") = "GPL";

generation_feedback:
**Assessment vs idea**

- The code clearly implements the intended idea: classify payload as `"GET "` vs `"SCAN "` and steer SCANs to a reserved subset of workers using only `pebble_agent_state` and `pebble_udp_targets`, with a single `bpf_sk_select_reuseport` call and simple O(1) logic.
- Logs confirm the split is actually happening:
  - At 80k (`agent-80000`): workers 0–4 see only GETs, worker 5 sees only SCANs:
    - e.g. `worker=0..4` each `gets≈12.3–12.5k, scans=0`; `worker=5 gets=0, scans=318 avg_scan≈2.0002ms`.
  - So classification is correct and all 6 workers are used, just asymmetrically (5 GET-only, 1 SCAN-only).
- Metrics show the behavior change matches the target of protecting GETs from SCAN head-of-line blocking:
  - Baseline (parent summary): GET p99/overall p99 blew up to ~16ms at 140k, ~450ms at 160k, ~1.4s at 180k.
  - This attempt (likely GET p99):
    - 80k: 0.359 ms
    - 100k: 3.333 ms
    - 140k: 6.876 ms
    - 160k: 9.449 ms
    - 180k: 469.78 ms  
  - That’s a *huge* improvement at 140k and especially 160k (from ~450ms to ~9ms), and a big improvement at 180k (from ~1.4s to ~470ms), while still using only reuseport/eBPF steering.

So in terms of **idea intent** (lower GET tail under mixed GET/SCAN without changing userspace or maps) this attempt is largely successful, especially around the 140–160k regime.

---

**Key behavior / issues from metrics and logs**

- **Worker utilization**
  - Workers 0–4: evenly loaded with GETs, no SCANs → good, unbiased GET hashing across GET workers.
  - Worker 5: only SCANs, no GETs → full isolation of SCAN traffic onto a single socket.
- **Effect on latency**
  - At 80k–160k, GET p99 is now dominated by queuing behind *other GETs*, not SCANs; p99 < 10ms even at 160k.
  - At 180k, p99 jumps to ~470ms. This is still overload behavior:
    - Even with SCAN isolation, 5 GET workers have finite capacity; at 180k we’re again driving the system *above* total GET service rate, so GETs now queue behind other GETs on those 5 sockets.
    - Additionally, the single SCAN worker is almost certainly saturated: all ~0.5–1% of SCANs are serialized on one 2ms-at-a-time goroutine. SCAN latencies will explode and can still contaminate higher percentiles if the scoring uses overall or mixed metrics anywhere.
- **Throughput considerations**
  - You’ve removed SCAN work from 5 workers and concentrated it on worker 5. For GETs this is great (they avoid 2ms head-of-line), but:
    - Worker 5’s CPU is effectively “sacrificed” to SCANs and can no longer help with GETs.
    - At very high offered rates (180k), this makes the GET cluster effectively 5 workers worth of capacity instead of 6; once the client drives beyond that capacity, GET queues still grow, hence the 469ms p99 at 180k.

Overall takeaway: the design **drastically improves GET p99 at moderate/high load (up to ~160k)**, but at the extreme overload point (180k) we still hit a capacity wall: 5 GET-only workers are not enough, and 1 SCAN-only worker is badly overloaded.

---

**Top changes to try next**

1. **Spread SCANs across a *small subset* of workers instead of exactly one**

   Goal: avoid completely sacrificing one core and reduce SCAN-queue blowups, while still keeping most workers clean for GETs.

   Concrete change (within EVOLVE-BLOCK):

   - Instead of hardcoding `scan_slots = 1`, make it proportional to `active`, but small. Example:

   ```c
   /* Reserve a small subset of high-index workers for SCANs. */
   __u32 scan_slots = active / 4;  // 25% of workers
   if (scan_slots == 0)
       scan_slots = 1;
   if (scan_slots >= active)
       scan_slots = active - 1;  // always leave at least 1 GET-only

   __u32 get_slots = active - scan_slots;

   if (is_scan) {
       __u32 idx_in_scan = pick_slot(rnd, scan_slots);
       slot = get_slots + idx_in_scan;      // scan workers: [get_slots, active)
   } else if (is_get) {
       slot = pick_slot(rnd, get_slots);    // GET workers: [0, get_slots)
   } else {
       goto random_all;
   }
   ```

   - With 6 workers, this yields `scan_slots=1` (no regression) or 2 depending on formula; you can tune divisor (e.g., `/3` to get 2 of 6). The experiment will tell whether a 2-of-6 SCAN subset improves behavior at 180k without tanking 140–160k.

2. **Ensure “unknown” or misparsed packets are treated as GET-like, not sent to SCAN slots**

   Today, “unknown” falls back to `random_all`, which can send them to the SCAN subset and reintroduce head-of-line risk for those requests.

   Change:

   - Instead of `goto random_all;` on unknown, treat them as GETs and keep them out of scan slots:

   ```c
   if (!is_get && !is_scan) {
       /* Treat unknown as GET-like: avoid scan slots. */
       __u32 scan_slots = 1;      // or same logic as above
       __u32 get_slots = active - scan_slots;
       slot = pick_slot(rnd, get_slots);
       (void)bpf_sk_select_reuseport(reuse, &pebble_udp_targets, &slot, 0);
       return SK_PASS;
   }
   ```

   - This keeps the SCAN subset dedicated to true SCANs while preserving the GET tail benefit even if the workload evolves or the parser occasionally fails.

3. **(More aggressive, if 180k still dominates the score) Allow a tiny fraction of GETs onto SCAN workers to reclaim some capacity**

   Only if experiments show the SCAN-only core is heavily underutilized for GET at 140–160k and you’re still missing the 180k target:

   - For GETs, introduce a second RNG branch to occasionally send a GET to the scan subset, e.g.:

   ```c
   // After determining is_get and having get_slots/scan_slots
   if (is_get) {
       __u32 base = pick_slot(rnd, get_slots);   // default: GET-only
       // Use low bits of rnd as a cheap coin flip
       if (scan_slots > 0 && (rnd & 0xF) == 0) { // ~1/16 of GETs
           __u32 idx_in_scan = (rnd >> 4) % scan_slots;
           slot = get_slots + idx_in_scan;       // occasionally to scan workers
       } else {
           slot = base;
       }
   }
   ```

   - This lets you tap a bit of extra GET capacity from scan workers while keeping the probability that a GET lands behind a 2ms SCAN very low (so p99 remains mostly unaffected, though some higher percentiles will move).

Try (1) and (2) first; they’re simple, verifier-safe, and keep the core idea intact. Then re-run the 140k/160k/180k sweeps to see if 180k GET p99 comes down further without regressing the excellent gains you already achieved at 160k.

